// Procedural score + foley for "The Pinch" — no samples, only synthesized sound.
// 48 kHz stereo, 10.0 s, written to assets/audio/score.wav
import fs from "node:fs";

const SR = 48000, DUR = 10, N = SR * DUR;
const L = new Float64Array(N), R = new Float64Array(N);
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const smooth = (a, b, t) => { const x = clamp((t - a) / (b - a), 0, 1); return x * x * (3 - 2 * x); };
function prng(seed) {
  let a = seed >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), 1 | t); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const rnd = prng(9137);

function addPan(i, v, pan) {
  const p = clamp((pan + 1) / 2, 0, 1);
  L[i] += v * Math.cos(p * Math.PI / 2);
  R[i] += v * Math.sin(p * Math.PI / 2);
}

// ---------------- room tone / pad ----------------
const padNotes = [
  [55.0, 0.020], [82.41, 0.010], [110.0, 0.016], [164.81, 0.007], [220.0, 0.004],
];
for (const [f, amp] of padNotes) {
  const detL = 1 + 0.0009, detR = 1 - 0.0009;
  const ph = rnd() * Math.PI * 2;
  for (let i = 0; i < N; i++) {
    const t = i / SR;
    const breath = 0.68 + 0.32 * Math.sin(2 * Math.PI * 0.045 * t + ph);
    const fade = smooth(0, 1.6, t) * (1 - smooth(9.6, 10, t) * 0.5);
    const lfo = 1 + 0.003 * Math.sin(2 * Math.PI * 0.13 * t + ph);
    const vl = Math.sin(2 * Math.PI * f * detL * lfo * t + 0.4 * Math.sin(2 * Math.PI * 0.06 * t));
    const vr = Math.sin(2 * Math.PI * f * detR * lfo * t + 0.4 * Math.sin(2 * Math.PI * 0.06 * t + 0.3));
    L[i] += amp * breath * fade * vl;
    R[i] += amp * breath * fade * vr;
  }
}

// brown room noise
{
  let bl = 0, br = 0;
  for (let i = 0; i < N; i++) {
    bl = bl * 0.995 + (rnd() * 2 - 1) * 0.004;
    br = br * 0.995 + (rnd() * 2 - 1) * 0.004;
    const fade = smooth(0, 1.2, i / SR) * (1 - smooth(9.7, 10, i / SR));
    L[i] += bl * 6 * fade; R[i] += br * 6 * fade;
  }
}

